// Unicode property ranges from the local web runtime (Node 24.20.0).
// Android's older ICU lacks Extended_Pictographic; keep the web's matcher
// independent of the phone's Unicode version, with no packaged pictures.
internal object EmojiText {
    private val pictograph = "[\\x{a9}\\x{ae}\\x{203c}\\x{2049}\\x{2122}\\x{2139}\\x{2194}-\\x{2199}\\x{21a9}-\\x{21aa}\\x{231a}-\\x{231b}\\x{2328}\\x{23cf}\\x{23e9}-\\x{23f3}\\x{23f8}-\\x{23fa}\\x{24c2}\\x{25aa}-\\x{25ab}\\x{25b6}\\x{25c0}\\x{25fb}-\\x{25fe}\\x{2600}-\\x{2604}\\x{260e}\\x{2611}\\x{2614}-\\x{2615}\\x{2618}\\x{261d}\\x{2620}\\x{2622}-\\x{2623}\\x{2626}\\x{262a}\\x{262e}-\\x{262f}\\x{2638}-\\x{263a}\\x{2640}\\x{2642}\\x{2648}-\\x{2653}\\x{265f}-\\x{2660}\\x{2663}\\x{2665}-\\x{2666}\\x{2668}\\x{267b}\\x{267e}-\\x{267f}\\x{2692}-\\x{2697}\\x{2699}\\x{269b}-\\x{269c}\\x{26a0}-\\x{26a1}\\x{26a7}\\x{26aa}-\\x{26ab}\\x{26b0}-\\x{26b1}\\x{26bd}-\\x{26be}\\x{26c4}-\\x{26c5}\\x{26c8}\\x{26ce}-\\x{26cf}\\x{26d1}\\x{26d3}-\\x{26d4}\\x{26e9}-\\x{26ea}\\x{26f0}-\\x{26f5}\\x{26f7}-\\x{26fa}\\x{26fd}\\x{2702}\\x{2705}\\x{2708}-\\x{270d}\\x{270f}\\x{2712}\\x{2714}\\x{2716}\\x{271d}\\x{2721}\\x{2728}\\x{2733}-\\x{2734}\\x{2744}\\x{2747}\\x{274c}\\x{274e}\\x{2753}-\\x{2755}\\x{2757}\\x{2763}-\\x{2764}\\x{2795}-\\x{2797}\\x{27a1}\\x{27b0}\\x{27bf}\\x{2934}-\\x{2935}\\x{2b05}-\\x{2b07}\\x{2b1b}-\\x{2b1c}\\x{2b50}\\x{2b55}\\x{3030}\\x{303d}\\x{3297}\\x{3299}\\x{1f004}\\x{1f02c}-\\x{1f02f}\\x{1f094}-\\x{1f09f}\\x{1f0af}-\\x{1f0b0}\\x{1f0c0}\\x{1f0cf}-\\x{1f0d0}\\x{1f0f6}-\\x{1f0ff}\\x{1f170}-\\x{1f171}\\x{1f17e}-\\x{1f17f}\\x{1f18e}\\x{1f191}-\\x{1f19a}\\x{1f1ae}-\\x{1f1e5}\\x{1f201}-\\x{1f20f}\\x{1f21a}\\x{1f22f}\\x{1f232}-\\x{1f23a}\\x{1f23c}-\\x{1f23f}\\x{1f249}-\\x{1f25f}\\x{1f266}-\\x{1f321}\\x{1f324}-\\x{1f393}\\x{1f396}-\\x{1f397}\\x{1f399}-\\x{1f39b}\\x{1f39e}-\\x{1f3f0}\\x{1f3f3}-\\x{1f3f5}\\x{1f3f7}-\\x{1f3fa}\\x{1f400}-\\x{1f4fd}\\x{1f4ff}-\\x{1f53d}\\x{1f549}-\\x{1f54e}\\x{1f550}-\\x{1f567}\\x{1f56f}-\\x{1f570}\\x{1f573}-\\x{1f57a}\\x{1f587}\\x{1f58a}-\\x{1f58d}\\x{1f590}\\x{1f595}-\\x{1f596}\\x{1f5a4}-\\x{1f5a5}\\x{1f5a8}\\x{1f5b1}-\\x{1f5b2}\\x{1f5bc}\\x{1f5c2}-\\x{1f5c4}\\x{1f5d1}-\\x{1f5d3}\\x{1f5dc}-\\x{1f5de}\\x{1f5e1}\\x{1f5e3}\\x{1f5e8}\\x{1f5ef}\\x{1f5f3}\\x{1f5fa}-\\x{1f64f}\\x{1f680}-\\x{1f6c5}\\x{1f6cb}-\\x{1f6d2}\\x{1f6d5}-\\x{1f6e5}\\x{1f6e9}\\x{1f6eb}-\\x{1f6f0}\\x{1f6f3}-\\x{1f6ff}\\x{1f7da}-\\x{1f7ff}\\x{1f80c}-\\x{1f80f}\\x{1f848}-\\x{1f84f}\\x{1f85a}-\\x{1f85f}\\x{1f888}-\\x{1f88f}\\x{1f8ae}-\\x{1f8af}\\x{1f8bc}-\\x{1f8bf}\\x{1f8c2}-\\x{1f8cf}\\x{1f8d9}-\\x{1f8ff}\\x{1f90c}-\\x{1f93a}\\x{1f93c}-\\x{1f945}\\x{1f947}-\\x{1f9ff}\\x{1fa58}-\\x{1fa5f}\\x{1fa6e}-\\x{1faff}\\x{1fc00}-\\x{1fffd}]"
    private val presentation = Regex("[\\x{231a}-\\x{231b}\\x{23e9}-\\x{23ec}\\x{23f0}\\x{23f3}\\x{25fd}-\\x{25fe}\\x{2614}-\\x{2615}\\x{2648}-\\x{2653}\\x{267f}\\x{2693}\\x{26a1}\\x{26aa}-\\x{26ab}\\x{26bd}-\\x{26be}\\x{26c4}-\\x{26c5}\\x{26ce}\\x{26d4}\\x{26ea}\\x{26f2}-\\x{26f3}\\x{26f5}\\x{26fa}\\x{26fd}\\x{2705}\\x{270a}-\\x{270b}\\x{2728}\\x{274c}\\x{274e}\\x{2753}-\\x{2755}\\x{2757}\\x{2795}-\\x{2797}\\x{27b0}\\x{27bf}\\x{2b1b}-\\x{2b1c}\\x{2b50}\\x{2b55}\\x{1f004}\\x{1f0cf}\\x{1f18e}\\x{1f191}-\\x{1f19a}\\x{1f1e6}-\\x{1f1ff}\\x{1f201}\\x{1f21a}\\x{1f22f}\\x{1f232}-\\x{1f236}\\x{1f238}-\\x{1f23a}\\x{1f250}-\\x{1f251}\\x{1f300}-\\x{1f320}\\x{1f32d}-\\x{1f335}\\x{1f337}-\\x{1f37c}\\x{1f37e}-\\x{1f393}\\x{1f3a0}-\\x{1f3ca}\\x{1f3cf}-\\x{1f3d3}\\x{1f3e0}-\\x{1f3f0}\\x{1f3f4}\\x{1f3f8}-\\x{1f43e}\\x{1f440}\\x{1f442}-\\x{1f4fc}\\x{1f4ff}-\\x{1f53d}\\x{1f54b}-\\x{1f54e}\\x{1f550}-\\x{1f567}\\x{1f57a}\\x{1f595}-\\x{1f596}\\x{1f5a4}\\x{1f5fb}-\\x{1f64f}\\x{1f680}-\\x{1f6c5}\\x{1f6cc}\\x{1f6d0}-\\x{1f6d2}\\x{1f6d5}-\\x{1f6d8}\\x{1f6dc}-\\x{1f6df}\\x{1f6eb}-\\x{1f6ec}\\x{1f6f4}-\\x{1f6fc}\\x{1f7e0}-\\x{1f7eb}\\x{1f7f0}\\x{1f90c}-\\x{1f93a}\\x{1f93c}-\\x{1f945}\\x{1f947}-\\x{1f9ff}\\x{1fa70}-\\x{1fa7c}\\x{1fa80}-\\x{1fa8a}\\x{1fa8e}-\\x{1fac6}\\x{1fac8}\\x{1facd}-\\x{1fadc}\\x{1fadf}-\\x{1faea}\\x{1faef}-\\x{1faf8}]")
    private val single = Regex(pictograph)
    private val part = pictograph + "(?:\\x{fe0f}|[\\x{1f3fb}-\\x{1f3ff}])?[\\x{e0020}-\\x{e007f}]*"
    private val pattern = Regex("[\\x{1f1e6}-\\x{1f1ff}]{2}|[#*0-9]\\x{fe0f}?\\x{20e3}|" + part + "(?:\\x{200d}" + part + ")*")

    fun matches(text: String): List<MatchResult> = pattern.findAll(text).filter {
        !single.matches(it.value) || presentation.containsMatchIn(it.value)
    }.toList()
}

internal fun emojiFile(emoji: String): String {
    val points = emoji.codePoints().toArray()
    val joined = 0x200d in points
    return points.filter { joined || it != 0xfe0f }.joinToString("-") { it.toString(16) }
}
